const categoryDefinitions: Record<string, string> = {
  "GIT & GITHUB": "GIT & GITHUB",
  "HR": "HR",
  "JAVA": "JAVA",
  "JavaScript": "JavaScript",
  "Kotlin": "Kotlin",
  "Kubernetes": "Kubernetes",
  "Linux": "Linux",
  "Machine Learning": "Machine Learning",
  "MongoDB": "MongoDB",
  "Microservices": "Microservices",
  "Next.js": "Next.js",
  "PostgreSQL": "PostgreSQL",
  "PreSales": "PreSales",
  "Python": "Python",
  "Quality Assurance": "Quality Assurance",
  "AWS": "Technology",
  "React": "React",
  "Redis": "Redis",
  "Software Engineering": "Software Engineering",
  "Spring Boot": "Spring Boot",
  "MySQL": "MySQL",
  "System Design": "System Design",
  "TypeScript": "TypeScript",
  "Web Development": "Web Development",
  "Advanced Java": "Advanced Java",
  "Android": "Android",
  "System Engineer": "System Engineer",
  "DOCKER": "DOCKER"
};

const slugify = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");

const buildCommonMistakes = (question: string) => [
  `Giving a memorized definition without explaining how it applies to: ${question}`,
  "Ignoring important trade-offs, limitations, edge cases, or operational concerns.",
  "Listing terminology without explaining the reasoning, practical example, or validation approach.",
];

async function main() {
  const prisma = new PrismaClient();

  try {
    const categoryCache = new Map<string, { id: string; subcategoryId: string }>();

    for (let i = 0; i < topics.length; i += 1) {
      const [topicCategory, question, slug, shortDescription, sampleAnswer] = topics[i];
      const categoryName = topicCategory;
      const desiredCategorySlug = slugify(categoryName);
      const group = categoryDefinitions[categoryName] ?? "Technology";

      let refs = categoryCache.get(categoryName);

      if (!refs) {
        // Resolve an existing category by its UNIQUE name first.
        // This prevents P2002 when an older seed used a different slug
        // for the same category name.
        let category = await prisma.category.findUnique({
          where: { name: categoryName },
        });

        // If the name is not present, try the desired unique slug.
        // If that slug already belongs to another category, reuse it
        // rather than attempting a conflicting create.
        if (!category) {
          category = await prisma.category.findUnique({
            where: { slug: desiredCategorySlug },
          });
        }

        if (category) {
          // Do not rename or change the slug of an existing category.
          // Only keep its existing identity so existing data remains safe.
          category = await prisma.category.update({
            where: { id: category.id },
            data: {
              group,
              description: category.description ?? `${categoryName} interview questions.`,
            },
          });
        } else {
          category = await prisma.category.create({
            data: {
              name: categoryName,
              slug: desiredCategorySlug,
              group,
              description: `${categoryName} interview questions.`,
            },
          });
        }

        const subcategorySlug = desiredCategorySlug;
        let subcategory = await prisma.subcategory.findUnique({
          where: {
            categoryId_slug: {
              categoryId: category.id,
              slug: subcategorySlug,
            },
          },
        });

        if (!subcategory) {
          subcategory = await prisma.subcategory.create({
            data: {
              name: categoryName,
              slug: subcategorySlug,
              categoryId: category.id,
            },
          });
        }

        refs = { id: category.id, subcategoryId: subcategory.id };
        categoryCache.set(categoryName, refs);
      }

      // IMPORTANT:
      // The source question fields are preserved. The update operation
      // changes ONLY sampleAnswer, as requested.
      //
      // The create operation supplies the required Prisma fields for a
      // question that does not already exist, while preserving the source
      // question, slug, and short description exactly.
      await prisma.interviewQuestion.upsert({
        where: { slug },
        update: {
          sampleAnswer,
        },
        create: {
          question,
          slug,
          categoryId: refs.id,
          subcategoryId: refs.subcategoryId,
          experienceLevel: ExperienceLevel.MID_LEVEL,
          difficulty: Difficulty.MEDIUM,
          interviewType: InterviewType.TECHNICAL,
          shortDescription,
          explanation: shortDescription || `Interview question about ${categoryName}.`,
          sampleAnswer,
          keyPoints: [],
          commonMistakes: buildCommonMistakes(question),
          followUpQuestions: [
            topics[(i + 1) % topics.length][1],
            topics[(i + 2) % topics.length][1],
            topics[(i + 3) % topics.length][1],
          ],
          tags: [categoryName],
          isPublished: true,
        },
      });
    }

    console.log(
      `Updated ${topics.length} source question rows. Existing questions were changed only in sampleAnswer.`,
    );
  } finally {
    await prisma.$disconnect();
  }
}

main().catch((error) => { console.error(error); process.exitCode = 1; });
